for (int i = 1; i <= 4; i++) {
  if (i == 2) continue;
  System.out.print(i);
}

int count = 0;
for (int i = 0; i < 2; i++) {
  for (int j = 0; j < 3; j++) {
    count++;
  }
}
System.out.print(count);

for (int i = 1; i < 10; i++) {
  if (i == 3) break;
  System.out.print(i);
}
